/*
 * prog27_soundex – reconstructed from the supplied binary.
 *
 * The original binary implements a classic Soundex encoder.
 * It expects a single command‑line argument.  If the argument is
 * missing or empty it prints the literal string "EMPTY".
 *
 * For a non‑empty argument it produces a 4‑character Soundex code:
 *
 *   1. The first character of the code is the first alphabetic
 *      character of the input (converted to upper case).
 *   2. The remaining three characters are digits derived from the
 *      remaining letters using the standard Soundex mapping:
 *
 *          B, F, P, V           -> 1
 *          C, G, J, K, Q, S, X, Z -> 2
 *          D, T                 -> 3
 *          L                    -> 4
 *          M, N                 -> 5
 *          R                    -> 6
 *          (all other characters, including vowels and
 *           non‑alphabetic symbols) -> 0 (ignored)
 *
 *   3. Consecutive duplicate digits (including a digit that would be
 *      produced by the first letter) are suppressed.
 *   4. The code is padded with '0' characters if fewer than three
 *      digits are generated.
 *
 * The program prints the resulting 4‑character string followed by a
 * newline (via `puts`), exactly matching the original binary's output.
 */

#include <stdio.h>
#include <string.h>
#include <ctype.h>

/* Return the Soundex digit for an upper‑case alphabetic character.
 * Non‑alphabetic characters return 0. */
static int soundex_digit(char ch)
{
    switch (ch) {
        case 'B': case 'F': case 'P': case 'V':
            return 1;
        case 'C': case 'G': case 'J': case 'K':
        case 'Q': case 'S': case 'X': case 'Z':
            return 2;
        case 'D': case 'T':
            return 3;
        case 'L':
            return 4;
        case 'M': case 'N':
            return 5;
        case 'R':
            return 6;
        default:
            return 0;               /* vowels, Y, H, W and any non‑letter */
    }
}

/* Produce the Soundex code for the supplied string.
 * The result buffer must have room for at least 5 bytes
 * (4 characters plus the terminating NUL). */
static void make_soundex(const char *src, char *dst)
{
    /* Find the first alphabetic character – this becomes the leading letter. */
    while (*src && !isalpha((unsigned char)*src))
        ++src;

    if (!*src) {                     /* no alphabetic characters at all */
        strcpy(dst, "EMPTY");
        return;
    }

    dst[0] = (char)toupper((unsigned char)*src);
    dst[1] = dst[2] = dst[3] = '0';
    dst[4] = '\0';

    int prev_digit = soundex_digit(dst[0]);   /* digit of the first letter (for duplicate suppression) */
    int filled = 0;                           /* how many digit positions have been filled */

    ++src;                                    /* advance past the first character */

    for ( ; *src && filled < 3; ++src) {
        if (!isalpha((unsigned char)*src))
            continue;                         /* skip non‑letters */

        char up = (char)toupper((unsigned char)*src);
        int d = soundex_digit(up);
        if (d == 0)
            continue;                         /* vowels etc. are ignored */

        if (d == prev_digit)
            continue;                         /* suppress consecutive duplicates */

        dst[filled + 1] = (char)('0' + d);
        ++filled;
        prev_digit = d;
    }
}

int main(int argc, char *argv[])
{
    if (argc < 2) {
        puts("EMPTY");
        return 0;
    }

    const char *input = argv[1];
    if (input == NULL || input[0] == '\0') {
        puts("EMPTY");
        return 0;
    }

    char result[5];          /* 4 characters + NUL */
    make_soundex(input, result);
    puts(result);
    return 0;
}
